R.append(T(3093,"आसान टर्की स्लॉपी जोज़","बीते ज़माने के अमेरिकी डाइनर का जश्न मनाने वाले एक स्वादिष्ट, परिवार के पसंदीदा व्यंजन का आनंद लें। लुइज़ियाना की DaVita रीनल आहार विशेषज्ञ टैमी आसान टर्की स्लॉपी जोज़ की एक किडनी-अनुकूल रेसिपी साझा करती हैं।","6","रेसिपी का 1/6 हिस्सा 1 हैमबर्गर बन पर",
["1/2 कप लाल प्याज़","1/2 कप हरी शिमला मिर्च","1-1/2 पाउंड कीमा टर्की, 7% वसा वाला","1 बड़ा चम्मच Mrs. Dash® Chicken Grilling Blend सीज़निंग","2 बड़े चम्मच ब्राउन शुगर","1 बड़ा चम्मच वूस्टरशायर सॉस","1 कप कम सोडियम वाला टमाटर सॉस","6 हैमबर्गर बन"],
["प्याज़ और शिमला मिर्च को काटें।","इन्हें टर्की के साथ एक बड़ी स्किलेट में रखें और मध्यम-तेज़ आँच पर टर्की के अंदर तक पकने तक पकाएँ। पानी या चर्बी न निथारें।","एक छोटे कटोरे में Mrs. Dash® सीज़निंग, चीनी, वूस्टरशायर सॉस और टमाटर सॉस मिलाएँ।","मसालों को टर्की के मिश्रण में डालें। आँच धीमी करें और 10 मिनट तक धीमी आँच पर पकाएँ।","6 हिस्सों में बाँटें और हैमबर्गर बन पर परोसें।"],
["कीमा टर्की की जगह कम चर्बी वाला कीमा बीफ़ इस्तेमाल किया जा सकता है। पहले चरण में बीफ़ को भूनने के बाद चर्बी निथार दें।","समय बचाने के लिए जमे हुए कटे प्याज़ और शिमला मिर्च का उपयोग करें।","कम प्रोटीन वाले आहार के लिए टर्की को घटाकर 1 पाउंड कर दें या अपनी आहार योजना के अनुसार मात्रा समायोजित की जा सकती है।"],["3 मांस","2 स्टार्च","1 सब्ज़ी, मध्यम पोटैशियम"]))
R.append(T(3095,"स्लो कुकर में शहद वाले बेक्ड सेब","अपनी अगली मिठाई की इच्छा के लिए स्लो कुकर में शहद वाले बेक्ड सेब की किडनी-अनुकूल रेसिपी आज़माएँ। स्लो कुकर में शहद वाले बेक्ड सेब की हमारी रेसिपी DaVita.com के लिए विशेष रूप से कैलिफ़ोर्निया की DaVita रीनल आहार विशेषज्ञ सारा ने बनाई है। क्लासिक बेक्ड सेब का यह आधुनिक, किडनी-अनुकूल रूप मधुमेह, डायलिसिस और बिना डायलिसिस वाले CKD आहार का पालन करने वालों के लिए एकदम सही है।","4","6 टुकड़े पके हुए सेब",
["3 मध्यम सेब","2 छोटे चम्मच दालचीनी","1/3 कप शहद","1 बड़ा चम्मच बिना नमक का मक्खन"],
["हर सेब का बीच का हिस्सा निकालकर उसे 8 टुकड़ों में काटें और स्लो कुकर में रखें।","सेब के टुकड़ों पर दालचीनी छिड़कें और लपेटने के लिए उछालकर मिलाएँ।","ऊपर से शहद डालें, मक्खन डालें और चलाएँ।","स्लो कुकर को धीमे तापमान पर सेट करें, ढक्कन से ढकें और 2 घंटे पकाएँ।"],
["यह रेसिपी ओवन में भी तैयार की जा सकती है। 325° F पर 45 से 60 मिनट पकाएँ।"],["1 फल","1 उच्च कैलोरी","1/2 वसा"]))
R.append(T(3097,"जर्मन एप्पल केक","जर्मन एप्पल केक मीठे सेबों के स्लाइस का मेल है जिन्हें मीठे नींबू-दालचीनी वाले घोल में मिलाया जाता है और फिर सुनहरा भूरा होने तक बेक किया जाता है। यह किडनी-अनुकूल केक इतना स्वादिष्ट है कि इस पर आइसिंग की ज़रूरत नहीं पड़ती।","15","1 टुकड़ा 3\" x 2-1/2\"",
["12 बड़े चम्मच बिना नमक का मक्खन","3 मध्यम गाला सेब","1 कप चीनी","1 नींबू","1 छोटा चम्मच वनीला एक्सट्रैक्ट","2 बड़े अंडे","2 कप मैदा","2 छोटे चम्मच दालचीनी","1 छोटा चम्मच बेकिंग सोडा","1/2 छोटा चम्मच नमक"],
["ओवन को 325° F पर पहले से गरम करें। 9 x 13 इंच की बेकिंग डिश में चिकनाई लगाएँ। मक्खन को नरम होने के लिए बाहर रखें। सेब छीलें, बीच का हिस्सा निकालें और स्लाइस में काटें।","मिक्सर से मक्खन और चीनी को हल्का और फूला हुआ होने तक फेंटें। नींबू का छिलका (ज़ेस्ट) कद्दूकस करें। नींबू का ज़ेस्ट और वनीला एक्सट्रैक्ट मक्खन और चीनी के मिश्रण में डालें। एक अंडा डालें और मिलाते रहें; दूसरा अंडा डालें और मिलाएँ।","एक अलग कटोरे में मैदा, दालचीनी, बेकिंग सोडा और नमक मिलाएँ। सूखी सामग्री को धीरे-धीरे फेंटे हुए मक्खन में मिलने तक डालें। ज़्यादा न मिलाएँ।","नींबू का रस निचोड़ें; रस को घोल में मिलाएँ। सेब के स्लाइस मिलाएँ।","घोल को चिकनाई लगी बेकिंग डिश में डालें। ऊपर से एक बड़ा चम्मच चीनी छिड़कें। 30 से 40 मिनट बेक करें। केक तब पक जाता है जब केक के बीच में डाली गई टूथपिक साफ निकले। केक के ठंडा होने के बाद उसे 15 टुकड़ों में काटें और परोसें।"],
["अपनी पसंद की सेब की किस्म इस्तेमाल करें।","कम कार्बोहाइड्रेट वाली सर्विंग (23 ग्राम) के लिए केक को 20 टुकड़ों में काटें।"],["1 स्टार्च","1 उच्च कैलोरी","2 वसा"]))
R.append(T(3099,"सुपर फ्रूट स्मूदी","फ़्लोरिडा की DaVita आहार विशेषज्ञ मार्लीन कहती हैं कि वे अपने मरीज़ों की देखभाल “मुर्गी माँ” की तरह करती हैं। और ज़्यादातर माँओं की तरह, उन्हें सेहत के लिए अच्छी चीज़ें खिलाना पसंद है। मार्लीन की सुपर फ्रूट स्मूदी एक बेहतरीन, किडनी-अनुकूल ट्रीट है।","2","10 औंस",
["8 औंस Vanilla Nepro® with Carb Steady™, ठंडा किया हुआ","100% व्हे प्रोटीन के 2 स्कूप","1 कप जमे हुए आड़ू या मिश्रित बेरियाँ","1/2 कप कुचली हुई बर्फ, वैकल्पिक"],
["जमे हुए फल को ब्लेंडर में डालें।","ठंडा किया हुआ Nepro®, व्हे प्रोटीन और कुचली हुई बर्फ (यदि चाहें) डालें।","चिकना होने तक ब्लेंड करें।","गिलास में डालें और स्ट्रॉ के साथ परोसें।"],
["बचे हुए हिस्से को बाद के लिए फ्रीज़ करें या फ्रिज में रखें।","रेसिपी के विश्लेषण में Beneprotein® व्हे प्रोटीन पाउडर, 7 ग्राम के स्कूप के मान इस्तेमाल किए गए थे। मिलते-जुलते उत्पादों के साथ पोषक तत्वों के मान थोड़े अलग हो सकते हैं।"],["2 मांस","1 फल, कम पोटैशियम","2 उच्च कैलोरी"]))
R.append(T(3101,"जिंजरब्रेड मफ़िन","ये जिंजरब्रेड मफ़िन आने वाले सालों तक त्योहारों की पसंदीदा बनने वाले हैं। तीखी अदरक, दालचीनी और ब्राउन शुगर के साथ मिलकर एक लाजवाब किडनी-अनुकूल मफ़िन बनाते हैं जो नाश्ते, मिठाई या स्नैक के लिए बेहतरीन है।","12","1 मफ़िन",
["2 बड़े अंडे","3/4 कप 1% कम वसा वाला दूध","6 बड़े चम्मच कैनोला तेल","1/2 कप कसकर भरी हुई ब्राउन शुगर","4 बड़े चम्मच गहरे रंग का कॉर्न सिरप","2 कप मैदा","1 बड़ा चम्मच बेकिंग पाउडर","4 छोटे चम्मच पिसी अदरक","1-1/2 छोटा चम्मच पिसी दालचीनी"],
["ओवन को 400° F पर पहले से गरम करें। 12 कप वाले मफ़िन पैन में चिकनाई लगाएँ या पेपर लाइनर बिछाएँ।","एक मध्यम कटोरे में अंडों को हल्का फेंटें। उसमें दूध, तेल, ब्राउन शुगर और कॉर्न सिरप फेंटकर मिलाएँ।","एक बड़े कटोरे में मैदा, बेकिंग पाउडर, अदरक और दालचीनी को मिलाएँ। सूखी सामग्री के बीच में गड्ढा बनाएँ और तरल सामग्री डालें। केवल मिलने तक धीरे से चलाएँ: ज़्यादा न मिलाएँ।","घोल को तैयार किए गए मफ़िन पैन में चम्मच से डालें। पहले से गरम ओवन में लगभग 20 मिनट बेक करें, जब तक वे सुनहरे भूरे और छूने पर सख़्त न हो जाएँ।","ओवन से निकालें और मफ़िन को पैन में 5 मिनट ठंडा होने दें। मक्खन या क्रीम चीज़ के साथ गरम परोसें।"],
["बचे हुए मफ़िन को बाद में झटपट नाश्ते के लिए फ्रीज़ करें। माइक्रोवेव में 30-45 सेकंड के लिए दोबारा गरम करें।","मफ़िन में बेकिंग पाउडर होता है जो फॉस्फोरस की मात्रा बढ़ाता है। जब मफ़िन स्नैक के रूप में खाए जाएँ तो फॉस्फेट बाइंडर लेने की ज़रूरत है या नहीं, यह अपने आहार विशेषज्ञ से पूछें।"],["1 स्टार्च","1 उच्च कैलोरी","1 वसा"]))
R.append(T(3103,"ब्रोकली-प्याज़ लैटकेस (पैनकेक)","एरिज़ोना की रीनल आहार विशेषज्ञ मार्जोरी ब्रोकली-प्याज़ लैटकेस (पैनकेक) की किडनी-अनुकूल रेसिपी साझा करती हैं, जिसमें आलू के विकल्प के रूप में प्याज़ और ब्रोकली का उपयोग किया जाता है, ताकि कम पोटैशियम वाले लैटकेस बनें जिनका आनंद कोई भी ले सके, यहाँ तक कि वे लोग भी जो किडनी-अनुकूल आहार पर हैं।","4","1 बड़ा लैटके या 2 छोटे लैटकेस",
["3 कप ब्रोकली के फूल","1/2 कप प्याज़","2 बड़े अंडे","2 बड़े चम्मच मैदा","2 बड़े चम्मच ऑलिव ऑयल"],
["ब्रोकली को छोटे टुकड़ों में काटें और प्याज़ काट लें।","कटी हुई ब्रोकली को थोड़े से पानी में 5 मिनट उबालें; पानी निथार दें।","अंडों को एक मध्यम कटोरे में तोड़कर फेंटें। मैदा डालें और अच्छी तरह मिलाएँ।","ब्रोकली और प्याज़ डालें और मैदे/अंडे के मिश्रण में अच्छी तरह मिलने तक चलाएँ।","फ्राइंग पैन में ऑलिव ऑयल डालें और गरम करें।","मिश्रण को चम्मच से गरम तेल में डालें, 4 बराबर हिस्से बनाएँ (या यदि छोटे लैटकेस चाहिए तो 8 हिस्से)।","स्पैचुला से लैटकेस को चपटा करें और दोनों तरफ भूरा होने तक तलें।","अतिरिक्त तेल सोखने के लिए पेपर टॉवल पर निथार लें।","गरमागरम परोसें।"],
["आलू के लैटकेस (पैनकेक), जो परंपरागत रूप से हनुक्का के दौरान परोसे जाते हैं, में तुलनात्मक सर्विंग के लिए 600 mg से अधिक पोटैशियम होता है, जब तक कि पोटैशियम घटाने के लिए आलू को भिगोया या उबाला न जाए। ब्रोकली-प्याज़ लैटकेस एक अच्छा कम पोटैशियम वाला विकल्प है।","लैटकेस का स्वाद तुरंत खाने पर सबसे अच्छा लगता है।"],["1/2 मांस","1 सब्ज़ी, मध्यम पोटैशियम","1 वसा"]))
R.append(T(3104,"ब्रेकफास्ट ट्रेल मिक्स","DaVita की आहार विशेषज्ञ वाई यिन यह सुनिश्चित करती हैं कि उनके डायलिसिस मरीज़ अपने दिन की शुरुआत नाश्ते से करें। वे ब्रेकफास्ट ट्रेल मिक्स की एक झटपट, चलते-फिरते बनने वाली रेसिपी साझा करती हैं। केवल 4 सामग्री के साथ इसे बनाना आसान है और इसे दूध के साथ या बिना दूध के, या कम पोटैशियम और फॉस्फोरस वाले दूध के विकल्प के साथ खाया जा सकता है।","3","1 कप",
["1 कप Corn Chex® सीरियल","1 कप Rice Chex® सीरियल","1/2 कप Cocoa Puffs® सीरियल","1/2 कप मिनी राइस केक (सादे या सेब-दालचीनी)"],
["एक मध्यम कटोरे में सभी सामग्री को एक साथ मिलाएँ।","1 कप के हिस्सों में बाँटें।","सूखा या अपने पसंदीदा दूध के विकल्प के साथ परोसें।"],
["ब्रेकफास्ट ट्रेल मिक्स उन डायलिसिस मरीज़ों के लिए नाश्ते का बेहतरीन विकल्प है जिनके पास अक्सर नाश्ते का समय नहीं होता। इसे स्नैक के रूप में या दूध के विकल्प के साथ नाश्ते के सीरियल के रूप में खाया जा सकता है।","रचनात्मक बनें और अलग-अलग सीरियल आज़माएँ। स्वीकृत सीरियल की सूची के लिए अपने आहार विशेषज्ञ से पूछें।"],["2 स्टार्च"]))
R.append(T(3108,"ज़ात्ज़िकी सॉस के साथ चने के बर्गर","ज़ात्ज़िकी सॉस के साथ चने के बर्गर पौधों पर आधारित भोजन में फाइबर बढ़ाने के लिए एकदम सही चुनाव है।","4","पिटा में 1 बर्गर, 1/4 कप ज़ात्ज़िकी सॉस",
["DaVita.com की ज़ात्ज़िकी सॉस रेसिपी का 1/2 हिस्सा","15 औंस डिब्बाबंद काबुली चने","4 छोटे हरे प्याज़ (स्कैलियन) या 2 बड़े हरे प्याज़","लाल प्याज़ के 4 स्लाइस","1 बड़ा अंडा","2 बड़े चम्मच मैदा","1 छोटा चम्मच सूखा ओरेगैनो","1/2 छोटा चम्मच पिसा जीरा","1/4 छोटा चम्मच नमक","2 बड़े चम्मच ऑलिव ऑयल","2 पिटा ब्रेड"],
["ज़ात्ज़िकी सॉस तैयार करें और उपयोग के समय तक फ्रिज में रखें।","काबुली चनों को धोकर निथार लें। हरे प्याज़ को छाँटकर स्लाइस में काटें। प्याज़ के स्लाइस काट लें।","फ़ूड प्रोसेसर में चने, हरे प्याज़, अंडा, मैदा, ओरेगैनो, जीरा और नमक डालें। ब्लेंड करें और तब तक पल्स करें जब तक दरदरा मिश्रण न बन जाए जो दबाने पर एक साथ टिके। मिश्रण नम होगा। 4 टिक्कियाँ बनाएँ।","स्किलेट में मध्यम आँच पर ऑलिव ऑयल गरम करें। गरम होने पर टिक्कियाँ डालें। सुनहरा होने और कुरकुरा होना शुरू होने तक पकाएँ, 4 से 5 मिनट। पलटें और सुनहरा भूरा और कुरकुरा होने तक 2 से 4 मिनट और पकाएँ।","पिटा को गरम करें और हर एक को आधा काट लें।","पिटा के आधे हिस्सों को सावधानी से खोलकर बर्गर तैयार करें। एक चने के बर्गर को आधा काटें और दोनों आधे हिस्सों को तस्वीर की तरह पिटा के अंदर रखें, ऊपर से ज़ात्ज़िकी सॉस और लाल प्याज़ का स्लाइस रखें।"],
["अतिरिक्त कुरकुरेपन के लिए सलाद के पत्ते और खीरे डालें।","काबुली चनों को छोले (garbanzo beans) भी कहा जाता है। लेबल की तुलना करें और सबसे कम सोडियम वाला उत्पाद चुनें।"],["1-1/2 स्टार्च","1 कम पोटैशियम वाली सब्ज़ी","1-1/2 वसा","1/2 दूध"]))
R.append(T(3111,"चीनी राइस नूडल्स","एशियाई संस्कृति में नए साल में सौभाग्य और अच्छी सेहत लाने के लिए बिना टूटे नूडल्स का व्यंजन खाया जाता है। यह किडनी-अनुकूल चीनी राइस नूडल्स रेसिपी पारंपरिक सोया सॉस की जगह कम सोडियम वाले कोकोनट अमीनोस का उपयोग करके सोडियम को कम रखती है।","6","1 कप",
["8 औंस राइस स्टिक्स","बड़े बोक चॉय के 4 पत्ते (1 कप कटे हुए)","सेलरी के 4 डंठल","1 बड़ी गाजर","1 मध्यम प्याज़","लहसुन की 5 कलियाँ","4 बड़े चम्मच कोकोनट अमीनोस","3/4 कप बिना नमक का बीफ़ या सब्ज़ी शोरबा","2 छोटे चम्मच Sriracha चिली सॉस","1 छोटा चम्मच कॉर्न स्टार्च","3 बड़े चम्मच कैनोला तेल","1 छोटा चम्मच तिल का तेल","1 हरा प्याज़"],
["राइस स्टिक्स को पैकेट के निर्देशों के अनुसार तैयार करें (आमतौर पर स्टिक्स को 20 मिनट ठंडे पानी में डुबोएँ और फिर अलग करें)।","बोक चॉय, सेलरी और गाजर को पतले स्लाइस में काटें। प्याज़ को छोटे टुकड़ों में काटें; लहसुन को बारीक काटें।","एक छोटे कटोरे में कोकोनट अमीनोस, शोरबा, चिली सॉस, लहसुन और कॉर्न स्टार्च मिलाएँ।","पैन को मध्यम-तेज़ आँच पर गरम करें और कैनोला और तिल का तेल डालें। कटा हुआ प्याज़ डालें और पारदर्शी होने तक पकाएँ। बोक चॉय, सेलरी और गाजर के स्लाइस डालें और हल्का कुरकुरा नरम होने तक चलाते हुए भूनें।","पकी हुई सब्ज़ियों में सॉस डालें और मिलाने के लिए चलाएँ।","राइस स्टिक्स के नरम हो जाने पर नूडल्स को अलग करें और सॉस और सब्ज़ियों वाले पैन में डालें। सब कुछ मिलाने के लिए चलाएँ।","स्वाद पूरी तरह विकसित होने के लिए परोसने से 15 मिनट पहले रख दें।","परोसने से पहले हरे प्याज़ को काटें और सजावट के लिए ऊपर छिड़कें।"],
["राइस स्टिक्स को राइस नूडल्स भी कहा जाता है।","आप राइस नूडल्स की जगह सोबा, उदोन, सेवइयाँ या स्पेगेटी इस्तेमाल कर सकते हैं। भिगोने की जगह निर्देशों के अनुसार तैयार करें।","इसे पूरा भोजन बनाने के लिए टोफू, झींगे या चिकन डालें।","इस रेसिपी में सोडियम को कम रखने के लिए सोया सॉस या तामारी की जगह कोकोनट अमीनोस का उपयोग किया गया है।"],["2 स्टार्च","1 सब्ज़ी, मध्यम पोटैशियम","1 वसा"]))
R.append(T(3113,"फलाफल","फलाफल, मध्य-पूर्व का पसंदीदा व्यंजन, स्नैक, भोजन या सलाद की टॉपिंग के रूप में बहुमुखी है। मुख्य सामग्री काबुली चने हैं, जो फाइबर बढ़ाने वाली फलीदार सामग्री है और सेहतमंदी में इज़ाफ़ा करती है। अतिरिक्त स्वाद के लिए लहसुन की सॉस और ताज़े खीरे डालें।","8","3 फलाफल",
["1 पाउंड सूखे काबुली चने","2 हरे प्याज़","2 कप सफेद प्याज़","1/2 कप अजमोद (पार्सले)","लहसुन की 4 कलियाँ","1/4 कप नींबू का रस","1-1/2 बड़े चम्मच मैदा","3/4 छोटा चम्मच नमक","1 छोटा चम्मच धनिया","1 बड़ा चम्मच जीरा","1/4 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच लाल मिर्च (केयेन)"],
["काबुली चनों को एक बड़े बर्तन में पानी में डुबोएँ और रात भर कमरे के तापमान पर भिगोएँ।","सफेद प्याज़ को बारीक काटें; हरे प्याज़, अजमोद और लहसुन को काट लें।","चनों को निथारकर धो लें। इन्हें हरे प्याज़, सफेद प्याज़, अजमोद, लहसुन, नींबू का रस, मैदा, नमक, धनिया, जीरा, काली मिर्च और लाल मिर्च के साथ फ़ूड प्रोसेसर में डालें।","जब तक मिश्रण दरदरे आटे से लेकर पेस्ट जैसी बनावट तक न पहुँच जाए, पल्स करें। (ज़्यादा न पीसें)। आपके फ़ूड प्रोसेसर के आकार के आधार पर आपको इसे 2 बार में करना पड़ सकता है। हो जाने पर काँटे से मिलाएँ और चनों के बड़े टुकड़े निकाल दें।","फलाफल के मिश्रण को 2 घंटे फ्रिज में रखें।","ओवन को 400° F पर पहले से गरम करें।","मफ़िन टिन पर कुकिंग स्प्रे करें।","स्कूप का उपयोग करें या मिश्रण को 24 गोलों में बेलें; इन्हें सीधे मफ़िन टिन में रखें। ओवन में रखें और 7 मिनट बेक करें। निकालें, फलाफल को पलटें और फिर 7 मिनट और बेक करें।"],
["फलाफल को खीरे, सलाद के पत्तों, प्याज़ और लहसुन की सॉस के साथ पिटा पॉकेट में या सलाद के ऊपर परोसें।","यदि टिक्कियाँ नहीं बन रही हैं, तो आपको उन्हें दोबारा फ़ूड प्रोसेसर में तब तक डालना पड़ सकता है जब तक वे अधिक पेस्ट जैसी न हो जाएँ। ध्यान रखें कि इसे हुमुस जैसी बनावट तक न पीसें।","बाँधने में मदद के लिए आप और मैदा डाल सकते हैं।","चाहें तो आप फलाफल को बेक करने की जगह तेल में तल सकते हैं। अंगूर के बीज या मूँगफली के तेल जैसा ऊँचे स्मोक पॉइंट वाला खाना पकाने का तेल इस्तेमाल करें।","फॉस्फोरस और पोटैशियम का सेवन लक्ष्य के भीतर रखने के लिए फलाफल को प्रोटीन वाले खाद्य पदार्थ के अतिरिक्त के रूप में नहीं, बल्कि उसके विकल्प के रूप में लें।"],["1 मांस","2 स्टार्च","1 सब्ज़ी, उच्च पोटैशियम"]))
R.append(T(3120,"हरी मटर का सलाद","मीठी हरी मटर, लाल प्याज़, थोड़े से कटे काले जैतून और मोज़रेला चीज़ को मलाईदार योगर्ट मेयोनेज़ सॉस में मिलाकर यह हरी मटर का सलाद सरल लेकिन स्वादिष्ट बनता है। यह दोपहर या रात के खाने, या पॉटलक आयोजन में ले जाने के लिए एकदम सही है।","8","1/2 कप",
["1/4 कप लाल प्याज़","4 ताज़ी तुलसी की पत्तियाँ","1/2 कप सादा ग्रीक योगर्ट","1/4 कप मेयोनेज़","3 कप जमी हुई हरी मटर","2.25 औंस डिब्बाबंद कटे काले जैतून (वैकल्पिक)","1/2 कप कद्दूकस किया हुआ मोज़रेला चीज़ (वैकल्पिक)"],
["प्याज़ को काटें और तुलसी को बारीक काटें।","एक छोटे कटोरे में मेयोनेज़ और योगर्ट मिलाएँ।","मटर को उबलते पानी में 2 से 3 मिनट पकाएँ। पानी निथारें और फिर मटर के गरम रहते हुए उसे मेयोनेज़-योगर्ट सॉस के साथ मिलाएँ।","प्याज़, तुलसी और जैतून को हरी मटर के मिश्रण में डालें और सामग्री को मिलाने के लिए चलाएँ।","ऊपर से मोज़रेला चीज़ छिड़कें और परोसने तक फ्रिज में रखें।"],
["तीन कप हरी मटर लगभग 1 पाउंड होती है। मौसम में होने पर ताज़ी हरी मटर इस्तेमाल करें।","सेहतमंद वसा शामिल करने के लिए ऑलिव ऑयल आधारित मेयोनेज़ चुनें।","यदि चाहें तो तुलसी की जगह अजमोद (पार्सले) का उपयोग करें।","कुरकुरेपन के लिए दो बड़े चम्मच कटे बादाम भी डाले जा सकते हैं।","अपनी इच्छा के अनुसार स्वाद के लिए काली मिर्च या Mrs. Dash® हर्ब सीज़निंग ब्लेंड डालें।"],["1 सब्ज़ी, कम पोटैशियम","1-1/2 वसा"]))
R.append(T(3121,"ताज़े टोफू स्प्रिंग रोल","ये हल्के और संतोषजनक स्प्रिंग रोल टोफू से प्रोटीन देते हैं और सब्ज़ियों के साथ मिलकर आपके किडनी आहार में एक ताज़ा विकल्प जोड़ते हैं।","6","2 स्प्रिंग रोल",
["रोमेन लेट्यूस के 12 पत्ते","2 मध्यम गाजर","1/2 मध्यम लाल प्याज़","16 औंस सख़्त टोफू","1/2 बड़ा चम्मच पिसा जीरा","1/2 बड़ा चम्मच दानेदार लहसुन (ग्रेन्युलेटेड गार्लिक)","1/4 छोटा चम्मच समुद्री नमक","1/2 छोटा चम्मच काली मिर्च","1 बड़ा चम्मच ऑलिव ऑयल","स्प्रिंग रोल के लिए 12 राइस रैपर"],
["लेट्यूस को धोकर सुखा लें, फिर हर पत्ते को लंबाई में आधा काटें। गाजर को जूलियन शैली (लंबी पतली पट्टियों) में काटें। प्याज़ के स्लाइस काटें। एक तरफ रख दें।","6 कप पानी उबालें और बाद में राइस रैपर भिगोने के लिए एक तरफ रख दें।","टोफू का पानी निथारें और थपथपाकर सुखा लें। इसे 12 टुकड़ों में काटें, हर एक लगभग 4″ लंबा।","टोफू को प्लेट पर फैलाएँ और उस पर जीरा, दानेदार लहसुन, समुद्री नमक और काली मिर्च समान रूप से छिड़कें।","नॉन-स्टिक पैन में ऑलिव ऑयल गरम करें। टोफू की पट्टियाँ पैन में मसाले वाली तरफ नीचे करके रखें। दूसरी तरफ मसाला लगाएँ और नीचे का हिस्सा हल्का भूरा होने तक, लगभग 1 से 2 मिनट तलें। पलटें और दूसरी तरफ हल्का भूरा होने तक तलें। टोफू को ठंडा होने के लिए प्लेट पर रखें।","एक बड़े उथले कटोरे में गरम पानी डालें। एक राइस रैपर को गरम पानी में डुबोएँ। जब वह थोड़ा नरम हो जाए, तो रैपर को एक बड़ी प्लेट पर रखें और रैपर के बीच में लेट्यूस के 2 आधे हिस्से रखें। लेट्यूस के ऊपर 2 से 3 बड़े चम्मच गाजर और 1 से 2 बड़े चम्मच कटा प्याज़ छिड़कें। सब्ज़ियों के ऊपर एक ठंडी की हुई टोफू की पट्टी रखें।","किनारों को अंदर की ओर मोड़ें, फिर नीचे का हिस्सा ऊपर मोड़ें और कसकर लपेटें। बाकी राइस रैपर, सब्ज़ियों और टोफू की पट्टियों के साथ दोहराएँ।","फ्रिज में रखें और अपनी पसंदीदा कम सोडियम वाली ड्रेसिंग के साथ ठंडा परोसें।"],
["2 बड़े चम्मच कम सोडियम वाली ड्रेसिंग के साथ परोसें। मिसो अदरक की ड्रेसिंग एक अच्छा विकल्प है।","इस रेसिपी में नमक की मात्रा बहुत कम है, फिर भी कुछ लोग बिना नमक वाले मसाले का उपयोग करके सोडियम की मात्रा और घटाना चाह सकते हैं। Mrs. Dash और Kirkland No Salt Seasoning अच्छे विकल्प हैं।"],["1 मांस","1 स्टार्च","1 सब्ज़ी, मध्यम पोटैशियम"]))
R.append(T(3122,"स्ट्रॉबेरी और क्रीम ओटमील","स्ट्रॉबेरी, ओट्स और सोया दूध इस उच्च फाइबर वाले एक-बर्तन के भोजन की मुख्य सामग्री हैं। स्ट्रॉबेरी और क्रीम ओटमील नाश्ते की पसंदीदा बन सकती है।","1","1-1/2 कप",
["1/2 कप ताज़ी स्ट्रॉबेरी","1 छोटा चम्मच चीनी (या पसंदीदा दानेदार स्वीटनर)","1/2 कप पानी","1/2 कप वनीला सोया दूध","2 बड़े चम्मच हाफ एंड हाफ क्रीमर","1/2 कप जल्दी पकने वाले ओट्स"],
["स्ट्रॉबेरी को काटें, फिर चीनी या दानेदार स्वीटनर से लपेटें। एक तरफ रख दें।","पानी, सोया दूध और हाफ एंड हाफ को एक छोटे बर्तन में मिलाएँ। मध्यम-तेज़ आँच पर हल्का उबाल आने दें।","स्ट्रॉबेरी डालें और उबाल आने दें।","ओट्स डालें और मनचाही गाढ़ाई तक 4 से 5 मिनट पकाएँ।"],
["अतिरिक्त मिठास के लिए शहद, एगेव या अपनी पसंद का स्वीटनर छिड़कें।","मौसम में होने पर स्ट्रॉबेरी की जगह रास्पबेरी या ब्लूबेरी आज़माएँ।","एक सर्विंग को एक-बर्तन का भोजन माना जाता है। यदि साइड डिश के रूप में परोस रहे हैं, तो मात्रा घटाकर 1/2 कप कर दें","ग्लूटेन-मुक्त आहार के लिए ओटमील के लेबल पर “ग्लूटेन-मुक्त” देखें।"],["2 स्टार्च","1/2 फल, कम पोटैशियम","1 दूध का विकल्प"]))
R.append(T(3125,"कैम्पफ़ायर ट्राउट","DaVita की आहार विशेषज्ञ हेलेन न केवल रसोई में माहिर हैं, बल्कि वे यह भी बता सकती हैं कि कोलोराडो में घूमा कैसे जाए। हेलेन कैम्पफ़ायर ट्राउट जैसी कुछ स्वादिष्ट किडनी-अनुकूल रेसिपी साझा करती हैं और रॉकी माउंटेन राज्य की यात्रा के लिए एक मज़ेदार कार्यक्रम बताती हैं। यदि आप जल्द ही कोलोराडो नहीं जा सकते, तब भी उनकी सिफ़ारिशें आपको ऐसा महसूस कराएँगी जैसे आपने छुट्टी मनाई हो।","4","1 फ़िले, 3 औंस पका हुआ",
["14 औंस ट्राउट फ़िले","1/2 छोटा चम्मच Mrs. Dash® Garlic & Herb सीज़निंग ब्लेंड","1 नींबू","2 हरे प्याज़","सेलरी का 1 डंठल","1 मध्यम गाजर"],
["चारकोल के कोयले तैयार करें।","नींबू और हरे प्याज़ को स्लाइस में काटें। सेलरी को काटें और गाजर को जूलियन शैली (लंबी पतली पट्टियों) में काटें।","मछली को फॉइल के एक बड़े टुकड़े के बीच में रखें (कैम्पफ़ायर के लिए मोटा फॉइल सबसे अच्छा रहता है)। Mrs. Dash सीज़निंग छिड़कें।","फ़िले के ऊपर नींबू के स्लाइस सजाएँ। हरे प्याज़, गाजर और सेलरी छिड़कें।","फॉइल को कसकर सील करें। इसे कैम्पफ़ायर के कोयलों के ऊपर जाली पर 10 से 15 मिनट या मछली के काँटे से आसानी से बिखरने तक रखें। (पैकेट खोलते समय सावधानी रखें क्योंकि भाप निकलेगी।)"],
["यदि चारकोल ग्रिल उपलब्ध न हो, तो मछली को ओवन में 400° F पर 10 से 15 मिनट बेक करें।","यदि आप कम प्रोटीन वाला आहार ले रहे हैं, तो मात्रा घटाकर 2 औंस (पकी हुई) कर दें, रेसिपी के लिए 6 हिस्से।"],["3 मांस","1/2 सब्ज़ी, मध्यम पोटैशियम"]))
R.append(T(3126,"कुरकुरा टोफू स्टर फ्राई","कुरकुरा टोफू स्टर फ्राई एक किडनी-अनुकूल शाकाहारी विकल्प है। आयोवा की DaVita आहार विशेषज्ञ जीन ने कुरकुरा टोफू स्टर फ्राई उन किडनी मरीज़ों के साथ साझा करने के लिए बनाया जो बिना मांस के ऐसे विकल्प ढूँढ रहे हैं जो फिर भी डायलिसिस आहार की आवश्यकताओं को पूरा करने के लिए उच्च गुणवत्ता वाला प्रोटीन प्रदान करें।","4","1 कप टोफू और सब्ज़ियाँ + 1/2 कप चावल",
["16 औंस अतिरिक्त सख़्त टोफू","1/2 लाल शिमला मिर्च","लहसुन की 1 कली","1-1/2 बड़ा चम्मच कम सोडियम वाला सोया सॉस","1-1/2 बड़ा चम्मच नींबू (लाइम) का रस","2 छोटे चम्मच चीनी","2 बड़े चम्मच कॉर्नस्टार्च","2 अंडे की सफेदी","1/2 कप बिना मसाले का ब्रेड क्रम्ब्स","1-1/2 बड़ा चम्मच कैनोला तेल","1 बड़ा चम्मच तिल का तेल","1 कप ताज़ी ब्रोकली के फूल","1 छोटा चम्मच Mrs. Dash® हर्ब सीज़निंग ब्लेंड","1/8 छोटा चम्मच काली मिर्च","1/8 छोटा चम्मच लाल मिर्च (केयेन)","1/2 छोटा चम्मच तिल","2 कप भाप में पका सफेद चावल"],
["टोफू को टुकड़ों में काटें। शिमला मिर्च को पट्टियों में काटें और लहसुन की कली को काट लें।","एक छोटे कटोरे में कम सोडियम वाला सोया सॉस, नींबू का रस और चीनी मिलाएँ। एक तरफ रख दें।","तीन अलग-अलग कटोरों में कॉर्नस्टार्च, अंडे की सफेदी और ब्रेड क्रम्ब्स रखें। टोफू के टुकड़ों को पहले कॉर्नस्टार्च में, फिर अंडे की सफेदी में डुबोएँ और ब्रेड क्रम्ब्स की परत चढ़ाएँ।","स्किलेट या कड़ाही में कैनोला तेल गरम करें और परत चढ़े टोफू को सुनहरा भूरा और कुरकुरा होने तक स्टर फ्राई करें। टोफू को पैन से निकालकर एक तरफ रख दें।","उसी पैन में तिल का तेल डालकर गरम करें। ब्रोकली और लाल शिमला मिर्च की पट्टियों को हल्का कुरकुरा नरम होने तक स्टर फ्राई करें। कटा हुआ लहसुन, Mrs. Dash सीज़निंग ब्लेंड, काली मिर्च और लाल मिर्च डालें और एक मिनट पकाएँ।","टोफू को वापस पैन में डालें और सब्ज़ियों के साथ उछालकर मिलाएँ। सोया-नींबू रस का मिश्रण ऊपर से डालें, तिल छिड़कें और चलाएँ। आँच से उतारें और 4 हिस्सों में बाँट दें। 1/2 कप चावल के साथ परोसें।"],
["यदि चाहें तो तिल के तेल की जगह ऑलिव ऑयल इस्तेमाल करें।","आप टुकड़ों में कटे टोफू को फ्रीज़ कर सकते हैं और बाद में पिघलाकर स्टर फ्राई कर सकते हैं। फ्रीज़ करने से टोफू को अधिक सख़्त, “मांस जैसी” बनावट मिलती है।","अपना पसंदीदा बिना नमक वाला मसाला इस्तेमाल करें। सुझाव: Penzey’s Spices®, Mrs. Dash® और Tone’s® कई तरह के बेहतरीन बिना नमक वाले मसाले बनाते हैं। पोटैशियम क्लोराइड वाले नमक के विकल्पों से बचें क्योंकि उनमें पोटैशियम अधिक होता है।"],["2 मांस","2-1/2 स्टार्च","1-1/2 सब्ज़ी, मध्यम पोटैशियम"]))
save(6,R)
